window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ee2c3fe82d5b1a11"]={"versions": [{"id": "FIG-ee2c3fe82d5b1a11", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Dateistruktur- und Inklusionsdiagramm (Include-Abhängigkeitsgraph). Im Architekturkontext der AUTOSAR Classic Platform (Basic Software, AUTOSAR Libraries) visualisiert das Diagramm die empfohlene modulinterne C-Quelldatei- und Header-Hierarchie für die Implementierung der mathematischen Festkomma- und Gleitkommabibliothek (MFX).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert vier dateibasierte Software-Entitäten und deren Inklusionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Mfx_&lt;name&gt;.c</code>: Übersetzungseinheit zur Implementierung von MFX-Routinen, wahlweise als Einzelfunktion (z. B. <code>Mfx_Add_u8u8_u8.c</code>) oder als Funktionsgruppe.</li>\n<li><code>Mfx.h</code>: Zentraler Schnittstellen- und Deklarations-Header des MFX-Moduls.</li>\n<li><code>std_types.h</code>: AUTOSAR-Standardtyp-Header zur Bereitstellung plattformweiter Basisdatentypen.</li>\n<li><code>memmap.h</code>: AUTOSAR Memory-Mapping-Header zur Steuerung der Speicherallokation und Sektionszuordnung via Präprozessor.</li>\n</ul>\n<p class=\"fig-p\">Beziehungen (<code>includes</code>):</p>\n<ul class=\"fig-list\">\n<li><code>Mfx_&lt;name&gt;.c</code> inkludiert <code>Mfx.h</code>.</li>\n<li><code>Mfx_&lt;name&gt;.c</code> inkludiert <code>memmap.h</code>.</li>\n<li><code>Mfx.h</code> inkludiert <code>std_types.h</code>.</li>\n<li><code>Mfx.h</code> inkludiert <code>memmap.h</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt keine dynamischen Laufzeit- oder Sequenzabläufe dar, sondern eine statische Präprozessor-Inklusionsordnung:</p>\n<ol class=\"fig-list\">\n<li>Beim Kompilieren einer MFX-C-Quelldatei (<code>Mfx_&lt;name&gt;.c</code>) wird primär <code>Mfx.h</code> eingebunden.</li>\n<li><code>Mfx.h</code> zieht transitiv <code>std_types.h</code> für grundlegende Typdefinitionen an.</li>\n<li>Sowohl im Header (<code>Mfx.h</code>) für Prototypen/Deklarationen als auch in der Quelldatei (<code>Mfx_&lt;name&gt;.c</code>) für Funktionsdefinitionen erfolgt die Einbindung von <code>memmap.h</code> zur Kapselung des compilerspezifischen Sektions-Mappings.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Bildunterschrift besitzt die Aufteilung der Implementierungsroutinen auf C-Dateien empfehlenden Charakter (Option 1: separate C-Datei pro Funktion; Option 2: gemeinsame C-Datei für Funktionsgruppen) ohne verbindliche Vorgabe.</p>\n<p class=\"fig-p\">Entwickler-Hinweise:</p>\n<ul class=\"fig-list\">\n<li>Die C-Dateien müssen stets <code>Mfx.h</code> einbinden, um Prototypen und Typschnittstellen konsistent zu halten.</li>\n<li>Für <code>memmap.h</code> ist das AUTOSAR-übliche Präprozessor-Muster einzuhalten (Setzen der modulspezifischen Sektions-Makros vor dem Inkludieren und Rücksetzen danach; <code>memmap.h</code> besitzt keine klassischen Include-Guards, da Mehrfachinklusion zwingend erforderlich ist).</li>\n<li>Dateinamen sind im Diagramm generisch in Kleinbuchstaben dargestellt (<code>std_types.h</code>, <code>memmap.h</code>); im realen AUTOSAR-Buildsystem sind die exakten Bezeichner (z. B. <code>Std_Types.h</code> und <code>MemMap.h</code> bzw. modulspezifisches MemMap) zu beachten.</li>\n</ul>"}, {"id": "FIG-b2cbf47fef88d974", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Dateistruktur- und Inklusionsdiagramm (Include-Abhängigkeitsgraph). Im Architekturkontext der AUTOSAR Classic Platform (Basic Software, AUTOSAR Libraries) visualisiert das Diagramm die empfohlene modulinterne C-Quelldatei- und Header-Hierarchie für die Implementierung der mathematischen Festkomma- und Gleitkommabibliothek (MFX).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert vier dateibasierte Software-Entitäten und deren Inklusionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Mfx_&lt;name&gt;.c</code>: Übersetzungseinheit zur Implementierung von MFX-Routinen, wahlweise als Einzelfunktion (z. B. <code>Mfx_Add_u8u8_u8.c</code>) oder als Funktionsgruppe.</li>\n<li><code>Mfx.h</code>: Zentraler Schnittstellen- und Deklarations-Header des MFX-Moduls.</li>\n<li><code>std_types.h</code>: AUTOSAR-Standardtyp-Header zur Bereitstellung plattformweiter Basisdatentypen.</li>\n<li><code>memmap.h</code>: AUTOSAR Memory-Mapping-Header zur Steuerung der Speicherallokation und Sektionszuordnung via Präprozessor.</li>\n</ul>\n<p class=\"fig-p\">Beziehungen (<code>includes</code>):</p>\n<ul class=\"fig-list\">\n<li><code>Mfx_&lt;name&gt;.c</code> inkludiert <code>Mfx.h</code>.</li>\n<li><code>Mfx_&lt;name&gt;.c</code> inkludiert <code>memmap.h</code>.</li>\n<li><code>Mfx.h</code> inkludiert <code>std_types.h</code>.</li>\n<li><code>Mfx.h</code> inkludiert <code>memmap.h</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt keine dynamischen Laufzeit- oder Sequenzabläufe dar, sondern eine statische Präprozessor-Inklusionsordnung:</p>\n<ol class=\"fig-list\">\n<li>Beim Kompilieren einer MFX-C-Quelldatei (<code>Mfx_&lt;name&gt;.c</code>) wird primär <code>Mfx.h</code> eingebunden.</li>\n<li><code>Mfx.h</code> zieht transitiv <code>std_types.h</code> für grundlegende Typdefinitionen an.</li>\n<li>Sowohl im Header (<code>Mfx.h</code>) für Prototypen/Deklarationen als auch in der Quelldatei (<code>Mfx_&lt;name&gt;.c</code>) für Funktionsdefinitionen erfolgt die Einbindung von <code>memmap.h</code> zur Kapselung des compilerspezifischen Sektions-Mappings.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Bildunterschrift besitzt die Aufteilung der Implementierungsroutinen auf C-Dateien empfehlenden Charakter (Option 1: separate C-Datei pro Funktion; Option 2: gemeinsame C-Datei für Funktionsgruppen) ohne verbindliche Vorgabe.</p>\n<p class=\"fig-p\">Entwickler-Hinweise:</p>\n<ul class=\"fig-list\">\n<li>Die C-Dateien müssen stets <code>Mfx.h</code> einbinden, um Prototypen und Typschnittstellen konsistent zu halten.</li>\n<li>Für <code>memmap.h</code> ist das AUTOSAR-übliche Präprozessor-Muster einzuhalten (Setzen der modulspezifischen Sektions-Makros vor dem Inkludieren und Rücksetzen danach; <code>memmap.h</code> besitzt keine klassischen Include-Guards, da Mehrfachinklusion zwingend erforderlich ist).</li>\n<li>Dateinamen sind im Diagramm generisch in Kleinbuchstaben dargestellt (<code>std_types.h</code>, <code>memmap.h</code>); im realen AUTOSAR-Buildsystem sind die exakten Bezeichner (z. B. <code>Std_Types.h</code> und <code>MemMap.h</code> bzw. modulspezifisches MemMap) zu beachten.</li>\n</ul>"}], "trans": [{"from": "FIG-ee2c3fe82d5b1a11", "to": "FIG-b2cbf47fef88d974", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
